```json
{
  "map": true,
  "subject": {
    "columns": ["protein_id"],
    "resolver": "pharos_protein_gene",
    "category": "biolink:Gene"
  },
  "object": {
    "columns": ["go_id"],
    "resolver": "curie",
    "category": "biolink:BiologicalProcess",
    "name_column": "go_term_text"
  },
  "predicate": "biolink:participates_in",
  "association_category": "biolink:GeneToGoTermAssociation",
  "knowledge_level": "knowledge_assertion",
  "agent_type": "not_provided",
  "primary_knowledge_source": "infores:goa",
  "qualifiers": {},
  "edge_properties": ["evidence", "goeco", "assigned_by", "go_term_text"],
  "keep_if": null,
  "split_by": "go_type",
  "by_value": {
    "Process": {
      "object": {
        "columns": ["go_id"],
        "resolver": "curie",
        "category": "biolink:BiologicalProcess",
        "name_column": "go_term_text"
      },
      "predicate": "biolink:participates_in",
      "association_category": "biolink:GeneToGoTermAssociation"
    },
    "Function": {
      "object": {
        "columns": ["go_id"],
        "resolver": "curie",
        "category": "biolink:MolecularActivity",
        "name_column": "go_term_text"
      },
      "predicate": "biolink:enables",
      "association_category": "biolink:GeneToGoTermAssociation"
    },
    "Component": {
      "object": {
        "columns": ["go_id"],
        "resolver": "curie",
        "category": "biolink:CellularComponent",
        "name_column": "go_term_text"
      },
      "predicate": "biolink:located_in",
      "association_category": "biolink:GeneToGoTermAssociation"
    }
  },
  "notes": "Each row is one GO annotation of a human reviewed UniProt protein, mapped to its gene via pharos_protein_gene. The GO aspect (go_type) selects the node category and predicate: Process to BiologicalProcess with participates_in, Function to MolecularActivity with enables, Component to CellularComponent with located_in. involved_in is not in Biolink 4.4.3, so participates_in is used for Process. The association class is GeneToGoTermAssociation. The evidence code is kept as an edge property, not used to pick the knowledge level, since the evidence mix spans automated and experimental claims. Agent type is not_provided for the same reason. knowledge_assertion is a choice a reader may question, since IEA rows are electronic inferences. go_id values are compact GO CURIEs, so the curie resolver applies directly."
}
```
